-- Adds the three-band Class Starter rubric (Excellent / Partial Credit /
-- No Credit) to the rubric library with revision 1 as its current revision.
-- Inserts only when missing. Never updates an existing rubric, and never
-- changes which rubric any assignment type uses: an admin selects it for
-- Class Starter in Admin → Assignment Types.
-- Generated by packages/prisma/scripts/generate-class-starter-three-band-migration.ts
SET lock_timeout = '5s';

DO $$
DECLARE
  schema_json JSONB := '{"name":"class-starter-three-band","title":"Class Starter (Excellent / Partial Credit / No Credit)","scoringScale":{"type":"points_scale","minScore":0,"maxScore":2},"rubric":{"categories":[{"key":"engagement","label":"Engagement","weight":1,"description":"Whether the student actually wrote and actually reflected on the prompt: Excellent for real engagement, Partial Credit for a start that stops short, No Credit for nothing that responds.","scoreLabels":[{"value":0,"label":"No Credit"},{"value":1,"label":"Partial Credit"},{"value":2,"label":"Excellent"}],"feedbackEnabled":false,"grammarHighlighting":false}]},"promptConfig":{"gradingInstructions":"You are reading a Class Starter entry: a short, open-ended piece of writing done to begin class. It is low-stakes, exploratory, and effort-based.\n\nJudge one thing: engagement. Engagement is whether the student actually wrote and actually reflected. Read for whether they took the prompt somewhere of their own and gave the entry real effort — not for whether the writing is polished, and not for whether the thinking is sophisticated.\n\nWeigh substance over length. A short entry that follows one idea honestly is engaged; a long one that circles the prompt without committing to anything is not.\n\nDo not grade grammar, spelling, punctuation, or formatting, and do not comment on them. Rough edges are expected here and never lower the score.\n\nThis is not a formally graded writing assignment. Honest effort earns full credit.\n\nScore engagement using these words exactly:\n- 2, Excellent: the student engaged with the prompt and reflected; the entry is a real, good-faith response.\n- 1, Partial Credit: the student touched the prompt but stopped short — a start, a single thin line, or writing that drifts away from what was asked.\n- 0, No Credit: nothing to read, or nothing that responds to the prompt.\n\nWrite the overall feedback to the student about their engagement: what they reached for, and the one thing that would take the next entry further. Keep it warm and brief."},"outputSchema":{"responseShape":"categories_overall_comment","schemaVersion":1},"calibrationNotes":"Soft, effort-based, three bands. Excellent is full credit for real engagement; Partial Credit for a start that stops short; No Credit only when nothing responds to the prompt."}'::jsonb;
  revision_id TEXT := gen_random_uuid()::text;
  fp TEXT;
BEGIN
  IF EXISTS (SELECT 1 FROM "Rubric" WHERE "name" = 'class-starter-three-band') THEN
    RETURN;
  END IF;

  fp := encode(sha256(convert_to(canonical_json(schema_json), 'UTF8')), 'hex');

  IF NOT EXISTS (
    SELECT 1 FROM "RubricRevision" WHERE "rubricName" = 'class-starter-three-band'
  ) THEN
    INSERT INTO "RubricRevision" (
      "id", "rubricName", "version", "schemaJson", "fingerprint",
      "requestId", "requestHash", "createdBy", "reason"
    ) VALUES (
      revision_id, 'class-starter-three-band', 1, schema_json, fp,
      'class-starter-three-band-v1', fp,
      'migration-class-starter-three-band',
      'Class Starter on three bands: Excellent / Partial Credit / No Credit'
    );
  ELSE
    SELECT "id" INTO revision_id
    FROM "RubricRevision"
    WHERE "rubricName" = 'class-starter-three-band'
    ORDER BY "version" DESC
    LIMIT 1;
  END IF;

  INSERT INTO "Rubric" (
    "id", "createdAt", "updatedAt", "name", "title", "schemaJson", "currentRevisionId"
  ) VALUES (
    gen_random_uuid()::text, NOW(), NOW(), 'class-starter-three-band', 'Class Starter (Excellent / Partial Credit / No Credit)', schema_json, revision_id
  );
END $$;
